// Remembers the last 40 topics so the writer never repeats itself.
// NOTE: workflow static data only persists on PRODUCTION executions (an active
// workflow). Manual test runs always start from an empty list.
const cfg = $input.first().json;
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.recentTopics)) store.recentTopics = [];

const recentTopics = store.recentTopics.slice(-40);

// Asking the model for a word count is far more reliable than asking it to
// reason about seconds. Spoken narration runs at roughly 2.5 words/second.
const targetWords = Math.round(Number(cfg.targetSeconds || 30) * 2.5);
// Small models hit a per-sentence budget far more reliably than a total.
const perSceneWords = Math.round(targetWords / Math.max(1, Number(cfg.sceneCount || 5)));

// The writer prompt is built here so the HTTP node body stays readable.
const promptText = "Channel niche: {{ $json.niche }}
Audience: {{ $json.audience }}
Language: {{ $json.language }}
Target length: about {{ $json.targetSeconds }} seconds of speech
Scene count: exactly {{ $json.sceneCount }}
Already covered (do NOT repeat these): {{ ($json.recentTopics || []).join("; ") || "nothing yet" }}

Write one short-form video script. Rules:
1. Scene 1 is the hook: under twelve words, opens an information gap, no greeting, no "did you know".
2. One spoken sentence per scene. Plain words. No emoji, markdown, quotes, parentheses or hashtags.
3. Spell every number out as words ("nineteen sixty nine", not "1969") and avoid abbreviations.
4. Use plain ASCII punctuation only. No curly quotes, no em dashes, no accented characters.
5. Every claim must be a well-established fact a viewer could verify. If you are not
   confident a detail is true, pick a different topic. Never invent a phenomenon.
6. The final scene lands the payoff and ends with a natural call to action for the channel.
7. Length: about {{ $json.targetWords }} words of narration in total, which is roughly
   {{ $json.perSceneWords }} words in every scene after the hook. Count the words in each
   sentence before you answer — a short script makes the finished video too brief.
8. visualQuery is two to four plain words naming concrete, filmable stock footage for that line
   (an object, place or action — never an abstract idea).

Return exactly this JSON shape:
{
  "topic": "short topic label",
  "title": "YouTube Shorts title under seventy characters",
  "description": "two or three sentence description",
  "tags": ["five to ten lowercase tags"],
  "musicTag": "one of: ambient, cinematic, inspiring, chill, suspense, calm, dramatic, rock, piano",
  "scenes": [{ "narration": "one sentence", "visualQuery": "two to four words" }]
}"
  .replace('{{ $json.niche }}', cfg.niche)
  .replace('{{ $json.audience }}', cfg.audience)
  .replace('{{ $json.language }}', cfg.language)
  .replace(/\{\{ \$json\.targetSeconds \}\}/g, String(cfg.targetSeconds))
  .replace('{{ $json.targetWords }}', String(targetWords))
  .replace('{{ $json.perSceneWords }}', String(perSceneWords))
  .replace('{{ $json.sceneCount }}', String(cfg.sceneCount))
  .replace('{{ ($json.recentTopics || []).join("; ") || "nothing yet" }}', recentTopics.join('; ') || 'nothing yet');

return [{ json: { ...cfg, recentTopics, promptText } }];

