// Parses the writer's JSON, sanity-checks it, and builds the exact narration
// string that will be sent to TTS. Everything downstream reads this node.
const cfg = $('Channel Config').first().json;
const res = $input.first().json;

const content = res?.choices?.[0]?.message?.content;
if (!content) {
  throw new Error('The model returned no content: ' + JSON.stringify(res).slice(0, 400));
}

let script;
try {
  script = JSON.parse(content);
} catch (e) {
  const m = /\{[\s\S]*\}/.exec(content);
  if (!m) throw new Error('The model did not return JSON:\n' + content.slice(0, 400));
  script = JSON.parse(m[0]);
}

// Models slip curly quotes and dashes in even when told not to, and unusual
// characters make the voice stumble. Normalise to ASCII before anything counts
// words or reaches the synthesiser.
const toAscii = (s) =>
  String(s)
    .replace(/[\u2018\u2019\u02BC]/g, "'")
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u2013\u2014]/g, '-')
    .replace(/\u2026/g, '...')
    .replace(/\s+/g, ' ')
    .trim();

const scenes = Array.isArray(script.scenes) ? script.scenes : [];
if (!scenes.length) throw new Error('The model returned no scenes.');
for (const [i, s] of scenes.entries()) {
  if (!s || typeof s.narration !== 'string' || !s.narration.trim()) {
    throw new Error(`Scene ${i + 1} has no narration.`);
  }
  s.narration = toAscii(s.narration);
  if (!s.visualQuery) s.visualQuery = script.topic || cfg.niche;
}

// The stock music catalogue matches single tags, so anything the model invents
// is coerced back onto a list of tags known to return results.
const MUSIC_TAGS = ['ambient', 'cinematic', 'inspiring', 'chill', 'suspense', 'calm', 'dramatic', 'rock', 'piano'];
const musicTag = MUSIC_TAGS.includes(String(script.musicTag || '').toLowerCase())
  ? String(script.musicTag).toLowerCase()
  : 'cinematic';

// One space between sentences. This exact string is what gets spoken, and the
// alignment that comes back is measured against it — which is what keeps
// captions and cuts frame-accurate.
const narration = scenes.map((s) => s.narration).join(' ');

const targetWords = Math.round(Number(cfg.targetSeconds || 30) * 2.5);
const wordCount = narration.split(/\s+/).filter(Boolean).length;
if (wordCount < targetWords * 0.6) {
  throw new Error(`The script is only ${wordCount} words for a ${cfg.targetSeconds}s video (expected around ${targetWords}). Retry, or use a stronger model.`);
}

const topic = String(script.topic || script.title || '').trim();
if (topic) {
  const store = $getWorkflowStaticData('global');
  if (!Array.isArray(store.recentTopics)) store.recentTopics = [];
  store.recentTopics.push(topic);
  store.recentTopics = store.recentTopics.slice(-40);
}

return [{
  json: {
    topic,
    title: String(script.title || topic || 'Untitled').slice(0, 100),
    description: String(script.description || ''),
    tags: Array.isArray(script.tags) ? script.tags.slice(0, 15) : [],
    musicTag,
    scenes,
    narration,
    wordCount,
    targetWords,
  },
}];

// One item per scene so the stock search below runs once per scene.
const script = $input.first().json;
return script.scenes.map((s, index) => ({
  json: { index, narration: s.narration, visualQuery: s.visualQuery },
}));

// Picks one b-roll clip per scene from the Zvid stock proxy.
// Portrait clips win because the canvas is 1080x1920 — a landscape clip still
// works via resize:"cover", it is just cropped harder.
const cfg = $('Channel Config').first().json;
const script = $('Parse script').first().json;
const responses = $input.all();
const approxSceneSeconds = Number(cfg.targetSeconds || 30) / Math.max(1, script.scenes.length);

function pick(items, needSeconds) {
  const usable = (items || []).filter((it) => it && it.src);
  if (!usable.length) return null;
  return usable
    .map((it) => {
      const portrait = Number(it.height) > Number(it.width);
      const longEnough = Number(it.duration || 0) >= needSeconds;
      return {
        it,
        score: (portrait ? 2 : 0) + (longEnough ? 1 : 0) + Math.min(1, Number(it.duration || 0) / 30),
      };
    })
    .sort((a, b) => b.score - a.score)[0].it;
}

const sceneMedia = script.scenes.map((_, i) => {
  const body = responses[i]?.json || {};
  const chosen = pick(body.items, approxSceneSeconds);
  if (!chosen) return null;
  return {
    kind: chosen.kind || 'video',
    src: chosen.src,
    duration: Number(chosen.duration) || null,
    width: Number(chosen.width) || null,
    height: Number(chosen.height) || null,
    credit: chosen.credit || null,
  };
});

const missing = sceneMedia.filter((m) => !m).length;
if (missing === sceneMedia.length) {
  throw new Error('No stock footage matched any scene. Make the visualQuery hints more concrete.');
}

return [{ json: { sceneMedia, missing } }];

// The music catalogue is tag-matched and occasionally returns nothing for a tag
// that worked a minute ago, so ask for the writer's tag plus two broad
// fallbacks. One item per query -> the search node runs once per tag.
const tag = $('Parse script').first().json.musicTag;
const queries = [...new Set([tag, 'cinematic', 'ambient'])];
return queries.map((query) => ({ json: { query } }));

// Rank the music candidates. Long tracks mean big files, and the renderer
// rejects any asset over the plan's audio size cap — a 6.3 MB track fails the
// WHOLE render, so a nice-to-have music bed must never be able to do that.
// Shortest-but-long-enough wins; the next node probes the real byte size.
const cfg = $('Channel Config').first().json;
const maxSeconds = Number(cfg.maxMusicSeconds ?? 200);

const seen = new Set();
const all = [];
for (const r of $input.all()) {
  for (const m of r.json.items || []) {
    if (!m || !m.src) continue;
    const key = m.id || m.src;
    if (seen.has(key)) continue;
    seen.add(key);
    all.push(m);
  }
}

const sized = all
  .filter((m) => { const d = Number(m.duration) || 0; return d >= 45 && d <= maxSeconds; })
  .sort((a, b) => (Number(a.duration) || 0) - (Number(b.duration) || 0));

const pool = (sized.length ? sized : all).slice(0, 4);
if (!pool.length) {
  // Nothing to probe — send one item the probe can hit harmlessly.
  return [{ json: { candidate: null, probeUrl: cfg.apiUrl } }];
}
return pool.map((candidate) => ({ json: { candidate, probeUrl: candidate.src } }));

// Keep the first candidate that is actually downloadable and within the size
// cap, then collapse to ONE item — otherwise the voiceover step downstream
// would run once per candidate. No usable track just means no music bed; it
// must never fail the run.
const cfg = $('Channel Config').first().json;
const limit = Number(cfg.maxMusicBytes ?? 5242880);
const shortlist = $('Shortlist music').all().map((i) => i.json);
const probes = $input.all();

let music = null;
const rejected = [];
for (let i = 0; i < probes.length; i += 1) {
  const candidate = shortlist[i] && shortlist[i].candidate;
  if (!candidate) continue;
  const p = probes[i] ? probes[i].json : {};
  const status = Number(p.statusCode);
  const headers = p.headers || {};
  const bytes = Number(headers['content-length'] || headers['Content-Length'] || 0);

  if (status !== 200) { rejected.push(`${candidate.id}: HTTP ${status || '?'}`); continue; }
  if (bytes && bytes > limit) { rejected.push(`${candidate.id}: ${bytes} bytes > ${limit}`); continue; }
  music = candidate;
  break;
}

return [{ json: { music, checked: probes.length, rejected } }];

// Turns one ElevenLabs "with-timestamps" response into (a) an mp3 binary ready
// for upload and (b) word timings.
//
// The alignment comes from the synthesiser itself, so the timings ARE the audio
// — there is no separate transcription step to disagree with, and nothing that
// can drift. That is the whole reason this endpoint is used instead of plain
// text-to-speech.
const res = $input.first().json;

if (!res || !res.audio_base64) {
  throw new Error(
    'ElevenLabs returned no audio. Check the xi-api-key credential, the voiceId, and your character quota. Response: ' +
      JSON.stringify(res).slice(0, 300)
  );
}

const a = res.alignment || res.normalized_alignment;
if (!a || !Array.isArray(a.characters)) {
  throw new Error('ElevenLabs returned audio but no alignment — make sure the URL ends in /with-timestamps.');
}

const chars = a.characters;
const starts = a.character_start_times_seconds || [];
const ends = a.character_end_times_seconds || [];

// Alignment is per CHARACTER; group runs of non-whitespace into words.
const words = [];
let cur = null;
for (let i = 0; i < chars.length; i += 1) {
  const ch = chars[i];
  if (/\s/.test(ch)) {
    if (cur) { words.push(cur); cur = null; }
    continue;
  }
  if (!cur) cur = { text: ch, start: Number(starts[i]), end: Number(ends[i]) };
  else { cur.text += ch; cur.end = Number(ends[i]); }
}
if (cur) words.push(cur);

if (!words.length) throw new Error('Alignment contained no words.');

const duration = Number(ends[ends.length - 1]) || words[words.length - 1].end;

return [{
  json: { words, duration, wordCount: words.length },
  // n8n binary payloads carry base64 in `data`; naming it matters because Zvid
  // derives the media kind from the MIME type on upload.
  binary: {
    data: {
      data: res.audio_base64,
      mimeType: 'audio/mpeg',
      fileName: 'voiceover.mp3',
      fileExtension: 'mp3',
    },
  },
}];

// Assembles the Zvid project JSON: one scene per narration sentence, cuts
// aligned to real word timings, word-timed captions, music bed and outro.
const cfg = $('Channel Config').first().json;
const script = $('Parse script').first().json;
const sceneMedia = $('Pick scene clip').first().json.sceneMedia;
const music = $('Pick music').first().json.music || null;
const upload = $('Upload voiceover').first().json.upload;
const timings = $('Voice + timings').first().json;

if (!upload || !upload.url) {
  throw new Error('The voiceover upload returned no URL: ' + JSON.stringify($('Upload voiceover').first().json).slice(0, 300));
}

const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
const round = (n) => Math.round(n * 100) / 100;
const escapeHtml = (s) =>
  String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

// ---- narration timing ---------------------------------------------------
const words = (Array.isArray(timings.words) ? timings.words : [])
  .map((w) => ({ text: String(w.text ?? '').trim(), start: Number(w.start), end: Number(w.end) }))
  .filter((w) => w.text && Number.isFinite(w.start) && Number.isFinite(w.end));

const narrationEnd = words.length ? words[words.length - 1].end : Number(timings.duration) || 30;
const audioDuration = Math.max(Number(timings.duration) || 0, narrationEnd);

// Apostrophes stay inside the word (both ASCII and curly) so "planet's" counts
// as one word here and one word in the transcript.
const countWords = (s) =>
  String(s || '').replace(/[^\p{L}\p{N}'\u2019]+/gu, ' ').trim().split(/\s+/).filter(Boolean).length;

const perScene = script.scenes.map((s) => countWords(s.narration));
const totalScripted = perScene.reduce((a, b) => a + b, 0);

// The alignment covers the exact text that was spoken, so walking the word
// stream by per-scene word count puts every cut on a sentence boundary. If the
// tokenisation drifts (digits, abbreviations) fall back to a proportional split
// so the render can never desync.
const drift = totalScripted ? Math.abs(words.length - totalScripted) / totalScripted : 1;
const useWordMap = words.length > 0 && drift <= 0.2;

const spans = [];
if (useWordMap) {
  let cursor = 0;
  for (let i = 0; i < perScene.length; i += 1) {
    const start = cursor === 0 ? 0 : words[cursor - 1].end;
    cursor = Math.min(cursor + perScene[i], words.length);
    const last = words[cursor - 1];
    spans.push({ start, end: i === perScene.length - 1 ? audioDuration : last ? last.end : audioDuration });
  }
} else {
  const weightTotal = totalScripted || perScene.length;
  let t = 0;
  for (let i = 0; i < perScene.length; i += 1) {
    const start = t;
    t = i === perScene.length - 1 ? audioDuration : t + ((perScene[i] || 1) / weightTotal) * audioDuration;
    spans.push({ start, end: t });
  }
}
spans[spans.length - 1].end += Number(cfg.tailSeconds ?? 0.4);

// ---- scenes -------------------------------------------------------------
const transition = cfg.sceneTransition || null;
const tDur = transition ? Number(cfg.transitionSeconds ?? 0.35) : 0;
const minScene = Math.max(1.2, tDur * 3);

const scenes = spans.map((span, i) => {
  const visible = Math.max(minScene, round(span.end - span.start));
  const media = sceneMedia[i];
  const visuals = [];

  if (media && media.kind === 'video') {
    // videoEnd is measured in SOURCE time, so a clip played at speed s covers
    // "visible * s" seconds of source. Slowing a short clip down beats cutting
    // to black.
    const speed = media.duration && media.duration < visible
      ? clamp(round(media.duration / visible), 0.5, 1)
      : 1;
    const sourceWindow = round(visible * speed);
    visuals.push({
      type: 'VIDEO',
      src: media.src,
      resize: 'cover',
      position: 'center-center',
      anchor: 'center-center',
      volume: 0,
      videoBegin: 0,
      videoEnd: media.duration ? Math.min(media.duration, sourceWindow) : sourceWindow,
      ...(speed !== 1 ? { speed } : {}),
      zoom: { depth: Number(cfg.kenBurnsDepth ?? 1.12) },
    });
  } else if (media && media.kind === 'image') {
    visuals.push({
      type: 'IMAGE',
      src: media.src,
      resize: 'cover',
      position: 'center-center',
      anchor: 'center-center',
      exitEnd: visible,
      zoom: { depth: Number(cfg.kenBurnsDepth ?? 1.25) },
    });
  }

  const isLast = i === spans.length - 1;
  return {
    id: `scene-${i + 1}`,
    // A transition OVERLAPS its two scenes, which would drag every later cut
    // earlier and desync the voiceover. Padding each scene by the overlap keeps
    // every visible cut on its narration timestamp.
    duration: round(visible + (isLast ? 0 : tDur)),
    backgroundColor: cfg.brandBackground || '#0b0d12',
    ...(isLast || !transition ? {} : { transition, transitionDuration: tDur }),
    visuals,
  };
});

const outroSeconds = Number(cfg.outroSeconds ?? 0);
if (outroSeconds > 0) {
  if (transition) {
    const prev = scenes[scenes.length - 1];
    prev.duration = round(prev.duration + tDur);
    prev.transition = transition;
    prev.transitionDuration = tDur;
  }
  scenes.push({
    id: 'outro',
    duration: outroSeconds,
    backgroundColor: cfg.brandBackground || '#0b0d12',
    visuals: [{
      type: 'TEXT',
      html: `<div class="cta"><span class="k">${escapeHtml(cfg.channelHandle || '')}</span><b>${escapeHtml(cfg.outroText || 'Follow for more')}</b></div>`,
      position: 'center-center',
      anchor: 'center-center',
      // The layout warning checker reads `style`, not customCode CSS.
      style: { color: '#ffffff', fontFamily: cfg.font || 'Montserrat' },
      customCode: {
        // customCode captures ONE loop and repeats it. Capturing the whole
        // outro makes the pop play once and hold, instead of retriggering.
        animationDuration: Math.min(15, outroSeconds),
        css: `.cta{display:flex;flex-direction:column;align-items:center;gap:24px;font-family:${cfg.font || 'Montserrat'},sans-serif;text-align:center;animation:pop .5s cubic-bezier(.2,.8,.2,1) both}
.cta .k{font-size:44px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:${cfg.brandAccent || '#7CFFB2'}}
.cta b{font-size:92px;font-weight:900;line-height:1.05;color:#ffffff;max-width:880px}
@keyframes pop{from{opacity:0;transform:scale(.9)}to{opacity:1;transform:scale(1)}}`,
      },
    }],
  });
}

const totalDuration = round(
  scenes.reduce((sum, s) => sum + s.duration, 0) - tDur * Math.max(0, scenes.length - 1)
);

// ---- captions -----------------------------------------------------------
const perCue = Math.max(1, Number(cfg.captionWordsPerCue ?? 3));
const captions = [];
for (let i = 0; i < words.length; i += perCue) {
  const chunk = words.slice(i, i + perCue);
  captions.push({
    start: chunk[0].start,
    end: chunk[chunk.length - 1].end,
    text: chunk.map((w) => w.text).join(' '),
    words: chunk.map((w) => ({ start: w.start, end: w.end, text: w.text })),
  });
}

// ---- audio + overlay ----------------------------------------------------
const audios = [{ src: upload.url, volume: 1, enter: 0 }];
if (music) {
  audios.push({ src: music.src, volume: Number(cfg.musicVolume ?? 0.12), enter: 0, exit: totalDuration });
}

const visuals = [];
if (cfg.channelHandle) {
  visuals.push({
    type: 'TEXT',
    text: cfg.channelHandle,
    // x/y are ignored when a `position` preset is set, and TEXT has no
    // `margin` field — an inset watermark needs explicit coordinates.
    x: 540,
    y: 120,
    anchor: 'top-center',
    track: 5,
    opacity: 0.72,
    style: {
      fontFamily: cfg.font || 'Montserrat',
      fontSize: '38px',
      fontWeight: '700',
      color: '#ffffff',
      letterSpacing: '2px',
    },
  });
}

// ---- caption styling ----------------------------------------------------
// In box modes ("highlight") the chip behind the spoken word is drawn first and
// the text outline is drawn on top of it, so a heavy outline with no padding
// hides the chip and the word becomes unreadable. Box modes therefore get a
// thin outline plus padding; every other mode recolours the spoken word with
// the brand accent and keeps the heavy outline, which is what keeps captions
// readable over both dark and bright footage.
const BOX_MODES = ['highlight'];
const animation = cfg.captionAnimation || 'karaoke';
const usesBox = BOX_MODES.includes(animation);
const strokeWidth = Math.max(0, Number(cfg.captionStrokeWidth ?? 6));
const accent = cfg.brandAccent || '#7CFFB2';

const subtitle = {
  captions,
  animation,
  activeWord: usesBox
    ? { color: cfg.captionActiveColor || '#0b0d12', background: accent }
    : { color: accent },
  font: {
    family: cfg.font || 'Montserrat',
    size: Number(cfg.captionSize ?? 64),
    color: '#ffffff',
    bold: true,
    transform: 'uppercase',
  },
  stroke: { color: '#000000', width: usesBox ? Math.min(strokeWidth, 2) : strokeWidth },
  ...(usesBox ? { background: { padding: 14 } } : {}),
  position: 'center',
  margin: { x: 90, y: 0 },
  maxWordsPerLine: perCue,
};

const name = (String(script.title || 'faceless short').replace(/[^\p{L}\p{N} _-]+/gu, '').trim().slice(0, 60)) || 'faceless short';

const payload = {
  name,
  resolution: cfg.resolution || 'youtube-short',
  frameRate: Number(cfg.frameRate ?? 30),
  backgroundColor: cfg.brandBackground || '#0b0d12',
  outputFormat: 'mp4',
  scenes,
  visuals,
  audios,
  subtitle,
};

return [{
  json: {
    payload,
    meta: {
      title: script.title,
      description: script.description,
      tags: script.tags,
      topic: script.topic,
      narrationSeconds: round(audioDuration),
      totalDuration,
      sceneCount: scenes.length,
      captionCount: captions.length,
      cutsAlignedToSpeech: useWordMap,
      musicTrack: music ? music.description : null,
      credits: sceneMedia.filter(Boolean).map((m) => m.credit).filter(Boolean),
    },
  },
}];

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug — surface the field list instead of a
// generic HTTP error.
const res = $input.first().json;
const status = res.statusCode ?? (res.valid === true ? 200 : 400);
const body = res.body || { ...res, details: res.errors ?? res.details };

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => `  - ${d.field}: ${d.message}`).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error(`Zvid rejected the project (HTTP ${status}): ${body.message || body.error}\n${details}`);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Dry run: everything except the paid render. Read this output, open the draft
// in the editor, then set dryRun to false in Channel Config to go live.
const cfg = $('Channel Config').first().json;
const d = $('Check validation').first().json;
const scenes = d.payload.scenes.map((s, i) => `  ${i + 1}. ${s.duration}s  ${s.visuals[0]?.type || 'empty'}`).join('\n');

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = `${String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '')}/?project=${project.id}`;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    title: d.meta.title,
    topic: d.meta.topic,
    editorLink,
    draftId,
    creditsRequired: d.creditsRequired,
    videoSeconds: d.meta.totalDuration,
    narrationSeconds: d.meta.narrationSeconds,
    cutsAlignedToSpeech: d.meta.cutsAlignedToSpeech,
    captions: d.meta.captionCount,
    musicTrack: d.meta.musicTrack,
    warnings: d.warnings,
    sceneBreakdown: scenes,
    nextStep: editorLink
      ? 'Open editorLink to preview and tweak the draft. Set dryRun to false in Channel Config to render.'
      : 'Set dryRun to false in Channel Config to render this for real.',
    payload: d.payload,
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Channel Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error(`Render did not finish within ${cfg.timeoutMinutes} minutes (job ${job.id}, state ${job.state}).`);
}

return $input.all();

// Final report for the run.
const cfg = $('Channel Config').first().json;
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : job.result?.url;

let youTubeId = null;
try { youTubeId = $('Upload to YouTube').first().json.id || null; } catch (e) { /* not published */ }

return [{
  json: {
    published: Boolean(youTubeId),
    youTubeId,
    youTubeUrl: youTubeId ? `https://youtube.com/shorts/${youTubeId}` : null,
    title: build.meta.title,
    description: build.meta.description,
    tags: build.meta.tags,
    videoUrl: url,
    jobId: job.id,
    creditsCharged: build.creditsRequired,
    videoSeconds: build.meta.totalDuration,
    cutsAlignedToSpeech: build.meta.cutsAlignedToSpeech,
    stockCredits: build.meta.credits,
    channel: cfg.channelHandle,
  },
}];
